// Spotify PKCE OAuth — works entirely in the browser, no backend needed.
// Register https://ferrarismat.github.io/website/ as the Redirect URI in your
// Spotify Developer App. This single URI works for both production and local dev:
//   • Production: callback lands here, tokens stored, redirect to #/test
//   • Local dev:  callback lands on production, tokens are bridged back to
//                 localhost via URL params (see Approot.js token-bridge handling)

const CLIENT_ID = process.env.REACT_APP_SPOTIFY_CLIENT_ID || '';

const SCOPES = [
  'streaming',
  'user-read-email',
  'user-read-private',
  'user-read-playback-state',
  'user-modify-playback-state',
].join(' ');

function getRedirectUri() {
  return process.env.REACT_APP_SPOTIFY_REDIRECT_URI || window.location.origin + '/';
}

// — PKCE helpers —

function generateVerifier(length = 128) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return Array.from(bytes).map(b => chars[b % chars.length]).join('');
}

async function generateChallenge(verifier) {
  const data = new TextEncoder().encode(verifier);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return btoa(String.fromCharCode(...new Uint8Array(hash)))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// — Public API —

export async function initiateSpotifyAuth() {
  const verifier = generateVerifier();
  const challenge = await generateChallenge(verifier);
  const state = generateVerifier(16);

  // Encode { state, verifier, callerOrigin } into the OAuth state param.
  // This lets the callback handler on a *different* origin (production) complete
  // the PKCE exchange and bridge tokens back to the caller (local dev).
  const stateEnvelope = btoa(JSON.stringify({
    s: state,
    v: verifier,
    o: window.location.origin,
  }));

  // Keep verifier/state in sessionStorage as a same-origin fallback
  sessionStorage.setItem('spotify_code_verifier', verifier);
  sessionStorage.setItem('spotify_auth_state', state);

  const params = new URLSearchParams({
    client_id: CLIENT_ID,
    response_type: 'code',
    redirect_uri: getRedirectUri(),
    scope: SCOPES,
    code_challenge_method: 'S256',
    code_challenge: challenge,
    state: stateEnvelope,
  });

  window.location.href = `https://accounts.spotify.com/authorize?${params}`;
}

// Returns { accessToken, devOrigin }
// devOrigin is non-null when the auth was initiated from a different origin
// (i.e. local dev) — Approot.js uses it to bridge tokens back.
export async function handleSpotifyCallback(code, rawState) {
  // Decode the state envelope (supports both cross-origin and same-origin flows)
  let stateValue, verifier, callerOrigin;
  try {
    const obj = JSON.parse(atob(rawState));
    stateValue = obj.s;
    verifier = obj.v;
    callerOrigin = obj.o;
  } catch {
    // Legacy / same-origin fallback: state is a plain random string
    stateValue = rawState;
    verifier = sessionStorage.getItem('spotify_code_verifier');
    callerOrigin = window.location.origin;
  }

  // Validate state when available (won't be in sessionStorage for cross-origin)
  const storedState = sessionStorage.getItem('spotify_auth_state');
  if (storedState && stateValue !== storedState) {
    throw new Error('State mismatch — possible CSRF');
  }

  const response = await fetch('https://accounts.spotify.com/api/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: CLIENT_ID,
      grant_type: 'authorization_code',
      code,
      redirect_uri: getRedirectUri(),
      code_verifier: verifier,
    }),
  });

  if (!response.ok) throw new Error('Token exchange failed');

  const tokens = await response.json();
  storeTokens(tokens);

  sessionStorage.removeItem('spotify_code_verifier');
  sessionStorage.removeItem('spotify_auth_state');

  const devOrigin = (callerOrigin && callerOrigin !== window.location.origin)
    ? callerOrigin
    : null;

  return { tokens, devOrigin };
}

function storeTokens(tokens) {
  const expiry = Date.now() + tokens.expires_in * 1000;
  localStorage.setItem('spotify_access_token', tokens.access_token);
  localStorage.setItem('spotify_token_expiry', String(expiry));
  if (tokens.refresh_token) {
    localStorage.setItem('spotify_refresh_token', tokens.refresh_token);
  }
}

async function refreshAccessToken() {
  const refreshToken = localStorage.getItem('spotify_refresh_token');
  if (!refreshToken) throw new Error('No refresh token stored');

  const response = await fetch('https://accounts.spotify.com/api/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: CLIENT_ID,
      grant_type: 'refresh_token',
      refresh_token: refreshToken,
    }),
  });

  if (!response.ok) throw new Error('Token refresh failed');

  const tokens = await response.json();
  storeTokens(tokens);
  return tokens.access_token;
}

export async function getSpotifyToken() {
  const token = localStorage.getItem('spotify_access_token');
  if (!token) return null;

  const expiry = Number(localStorage.getItem('spotify_token_expiry') || 0);
  if (Date.now() > expiry - 5 * 60 * 1000) {
    try {
      return await refreshAccessToken();
    } catch {
      clearSpotifyAuth();
      return null;
    }
  }

  return token;
}

export async function getSpotifyUserPlan(token) {
  try {
    const response = await fetch('https://api.spotify.com/v1/me', {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!response.ok) return null;
    const data = await response.json();
    return data.product || null; // 'premium' | 'free' | 'open' | 'student'
  } catch {
    return null;
  }
}

export function isSpotifyAuthenticated() {
  return !!localStorage.getItem('spotify_access_token');
}

export function clearSpotifyAuth() {
  localStorage.removeItem('spotify_access_token');
  localStorage.removeItem('spotify_refresh_token');
  localStorage.removeItem('spotify_token_expiry');
}
