// Spotify Search API — replaces iTunes for connected users.
// Returns the same normalized track shape as the iTunes service so the rest of
// the app stays unchanged.  Tracks with no preview_url are kept because the SDK
// player (Premium) can play any track via its URI; for preview mode they are
// filtered out downstream in useMusic.

const countryArtists = {
  GB: ['Hedex', 'Andy C', 'Goldie', 'Sub Focus', 'Wilkinson', 'High Contrast'],
  BE: ['Netsky', 'Andromedik', 'Murdock', 'Eptic'],
  NL: ['Noisia', 'Black Sun Empire', 'Nymfo'],
  AT: ['Mefjus', 'Camo & Krooked', 'DisasZt'],
  CZ: ['A-Cray', 'Forbidden Society'],
  DE: ['Phace', 'Current Value'],
  NZ: ['The Upbeats', 'State of Mind'],
  AU: ['Pendulum', 'ShockOne'],
  US: ['Dieselboy', 'Justin Hawkes'],
  CA: ['Bensley', 'Marcus Visionary', 'Gremlinz', 'Stranjah'],
  BR: ['DJ Marky', 'DJ Patife', 'Alibi'],
  ZA: ['Counterstrike'],
  JP: ['Makoto'],
  CO: ['Sigma'],
};

function normalizeTrack(item) {
  return {
    id: item.id,
    name: item.name,
    artist: item.artists.map(a => a.name).join(', '),
    album: item.album?.name || '',
    preview_url: item.preview_url || null,
    uri: item.uri,
    artwork: item.album?.images?.[0]?.url || null,
  };
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

async function searchArtist(artist, token, limit) {
  // Narrow to drum-and-bass genre for better accuracy
  const params = new URLSearchParams({
    q: `artist:"${artist}"`,
    type: 'track',
    limit: String(limit),
    market: 'US',
  });

  const response = await fetch(`https://api.spotify.com/v1/search?${params}`, {
    headers: { Authorization: `Bearer ${token}` },
  });

  if (!response.ok) return [];
  const data = await response.json();
  return (data.tracks?.items || []).map(normalizeTrack);
}

// Same interface as musicService.searchDnBTracks but accepts an access token.
export async function searchDnBTracks(countryCode, token, limit = 5) {
  const artists = countryArtists[countryCode] || ['drum and bass'];

  const results = await Promise.all(
    artists.map(artist => searchArtist(artist, token, limit))
  );

  const seen = new Set();
  const merged = [];
  for (const tracks of results) {
    for (const track of tracks) {
      if (!seen.has(track.id)) {
        seen.add(track.id);
        merged.push(track);
      }
    }
  }

  return shuffle(merged);
}
