// Spotify Web Playback SDK wrapper — Premium accounts only.
// Loads the SDK script on demand, creates a virtual Spotify Connect device in the
// browser, and exposes simple play / pause / volume controls.

let sdkLoadPromise = null;

function loadSDKScript() {
  if (sdkLoadPromise) return sdkLoadPromise;

  sdkLoadPromise = new Promise((resolve) => {
    // The SDK calls this global when it is ready
    window.onSpotifyWebPlaybackSDKReady = resolve;

    if (!document.querySelector('script[src*="spotify-player"]')) {
      const script = document.createElement('script');
      script.src = 'https://sdk.scdn.co/spotify-player.js';
      script.async = true;
      document.body.appendChild(script);
    }
  });

  return sdkLoadPromise;
}

export class SpotifySDKPlayer {
  constructor() {
    this.player = null;
    this.deviceId = null;
    this._getToken = null;
    this._onTrackEnd = null; // callback(channelId) — mirrors musicPlayer contract
  }

  // getToken: async () => string  — called by SDK whenever it needs a fresh token
  async init(getToken) {
    this._getToken = getToken;
    await loadSDKScript();

    this.player = new window.Spotify.Player({
      name: 'Globe DnB Player',
      getOAuthToken: cb => getToken().then(cb),
      volume: 1.0,
    });

    // Forward SDK track-end events to the hook's handler
    this.player.addListener('player_state_changed', state => {
      if (!state) return;
      // A track ends when playback pauses with position = 0 and the previous
      // track window differs from the current one (i.e. Spotify advanced).
      // Simpler heuristic: paused at position = 0 after playback started.
      if (state.paused && state.position === 0 && this._onTrackEnd) {
        this._onTrackEnd();
      }
    });

    await new Promise((resolve, reject) => {
      this.player.addListener('ready', ({ device_id }) => {
        this.deviceId = device_id;
        resolve();
      });
      this.player.addListener('not_ready', () => {
        this.deviceId = null;
      });
      this.player.addListener('initialization_error', ({ message }) =>
        reject(new Error('Spotify SDK init error: ' + message))
      );
      this.player.addListener('authentication_error', ({ message }) =>
        reject(new Error('Spotify auth error: ' + message))
      );
      this.player.addListener('account_error', ({ message }) =>
        reject(new Error('Spotify Premium required: ' + message))
      );

      this.player.connect();
    });
  }

  // Play a single track URI (or array of URIs as a mini-queue)
  async playTrack(trackUri) {
    if (!this.deviceId) return;
    const token = await this._getToken();
    const uris = Array.isArray(trackUri) ? trackUri : [trackUri];

    await fetch(`https://api.spotify.com/v1/me/player/play?device_id=${this.deviceId}`, {
      method: 'PUT',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ uris }),
    });
  }

  async pause() {
    if (this.player) await this.player.pause();
  }

  async resume() {
    if (this.player) await this.player.resume();
  }

  // volume: 0.0 – 1.0
  async setVolume(volume) {
    if (this.player) await this.player.setVolume(volume);
  }

  async getCurrentState() {
    if (!this.player) return null;
    return this.player.getCurrentState();
  }

  disconnect() {
    if (this.player) {
      this.player.disconnect();
      this.player = null;
      this.deviceId = null;
    }
  }
}
