import React, { useState, useEffect } from 'react';
import { Route, Switch } from 'react-router';
import { HashRouter } from 'react-router-dom';
import Home from './screens/Home';
import AKFN from './screens/AKFN';
import Test from './screens/Test';
import { handleSpotifyCallback } from './services/spotify/spotifyAuth';

export default function Approot() {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');
    const state = params.get('state');

    if (code && state) {
      // ── Spotify OAuth callback ──────────────────────────────────────────
      handleSpotifyCallback(code, state)
        .then(({ tokens, devOrigin }) => {
          if (devOrigin) {
            // Auth was initiated from a different origin (local dev).
            // Bridge tokens back via URL params so localhost can pick them up.
            const bridge = new URLSearchParams({
              _spotify_at: tokens.access_token,
              _spotify_rt: tokens.refresh_token || '',
              _spotify_exp: String(Date.now() + tokens.expires_in * 1000),
            });
            window.location.href = `${devOrigin}/?${bridge}`;
          } else {
            window.history.replaceState({}, '', window.location.pathname + '#/test');
            setReady(true);
          }
        })
        .catch(err => {
          console.error('Spotify callback error:', err);
          window.history.replaceState({}, '', window.location.pathname + '#/test');
          setReady(true);
        });

    } else if (params.get('_spotify_at')) {
      // ── Token bridge: production → localhost ────────────────────────────
      // The production site completed PKCE and sent tokens back here.
      const at = params.get('_spotify_at');
      const rt = params.get('_spotify_rt');
      const exp = params.get('_spotify_exp');
      if (at) localStorage.setItem('spotify_access_token', at);
      if (rt) localStorage.setItem('spotify_refresh_token', rt);
      if (exp) localStorage.setItem('spotify_token_expiry', exp);
      window.history.replaceState({}, '', window.location.pathname + '#/test');
      setReady(true);

    } else {
      setReady(true);
    }
  }, []);

  if (!ready) return null;

  return (
    <HashRouter>
      <Switch>
        <Route path="/" exact component={Home} />
        <Route path="/AKFN" exact component={AKFN} />
        <Route path="/test" exact component={Test} />
      </Switch>
    </HashRouter>
  );
}
