import { useState, useRef, useEffect, useCallback } from 'react';

// Music sources
import { searchDnBTracks as searchItunes } from '../services/music/musicService';
import { searchDnBTracks as searchSpotify } from '../services/spotify/spotifyService';

// Spotify auth
import {
  getSpotifyToken,
  getSpotifyUserPlan,
  isSpotifyAuthenticated,
  initiateSpotifyAuth,
  clearSpotifyAuth,
} from '../services/spotify/spotifyAuth';

// Spotify Web Playback SDK (Premium only)
import { SpotifySDKPlayer } from '../services/spotify/spotifyPlaybackSDK';

// HTML audio player (iTunes + Spotify preview modes)
import { getAudioElement, playOnChannel, pauseChannel, pauseAll } from '../services/music/musicPlayer';

// Audio analysis (used in iTunes / preview modes)
import { AudioMixer } from '../services/audio/audioAnalyser';
import { FrequencyTexture } from '../services/audio/frequencyTexture';
import { getCountryCode } from '../services/music/countryStoreMap';

// ─── Playback modes ─────────────────────────────────────────────────────────
// 'itunes'           – no Spotify auth; 30s iTunes previews, dual-channel
// 'spotify-preview'  – Spotify Free; 30s Spotify preview_url, dual-channel
// 'spotify-sdk'      – Spotify Premium; full tracks via Web Playback SDK

export function useMusic() {
  const [playing, setPlaying] = useState(false);
  const [mode, setMode] = useState('itunes'); // resolved on mount
  const [spotifyConnected, setSpotifyConnected] = useState(false);
  const [isPremium, setIsPremium] = useState(false);

  // ── Spotify ────────────────────────────────────────────────────────────────
  const spotifyTokenRef = useRef(null); // kept fresh; consumed by SDK and search
  const sdkPlayerRef = useRef(null);    // SpotifySDKPlayer instance (Premium)
  const sdkCurrentCountryRef = useRef(null); // country code currently on SDK

  // ── Dual-channel audio (iTunes / spotify-preview) ─────────────────────────
  const mixerRef = useRef(null);
  const freqTextureRef = useRef(null);
  const frequencyTextureRef = useRef(null);
  const audioReactiveRef = useRef(0.0);
  const analyserConnectedRef = useRef(false);

  const channelFreqTextureARef = useRef(null);
  const channelFreqTextureBRef = useRef(null);
  const channelFreqTexturesRef = useRef({ A: null, B: null });

  // ── Shared track cache ────────────────────────────────────────────────────
  const trackCacheRef = useRef({});       // countryCode -> tracks[]
  const trackIndexRef = useRef({});       // countryCode -> current index
  const channelAssignment = useRef({ A: null, B: null }); // channelId -> code
  const channelAssignmentRef = useRef({ A: null, B: null }); // exposed to Globe
  const fetchingRef = useRef({});         // in-flight guard
  const playingRef = useRef(false);

  // ── Frequency textures (created once, used in all modes) ──────────────────
  useEffect(() => {
    freqTextureRef.current = new FrequencyTexture();
    frequencyTextureRef.current = freqTextureRef.current.getTexture();
    channelFreqTextureARef.current = new FrequencyTexture();
    channelFreqTextureBRef.current = new FrequencyTexture();
    channelFreqTexturesRef.current = {
      A: channelFreqTextureARef.current.getTexture(),
      B: channelFreqTextureBRef.current.getTexture(),
    };
    return () => {
      freqTextureRef.current?.dispose();
      channelFreqTextureARef.current?.dispose();
      channelFreqTextureBRef.current?.dispose();
      mixerRef.current?.dispose();
      sdkPlayerRef.current?.disconnect();
    };
  }, []);

  // ── Resolve Spotify auth + plan on mount ─────────────────────────────────
  useEffect(() => {
    if (!isSpotifyAuthenticated()) return;

    getSpotifyToken().then(token => {
      if (!token) return;
      spotifyTokenRef.current = token;

      getSpotifyUserPlan(token).then(plan => {
        const premium = plan === 'premium';
        setSpotifyConnected(true);
        setIsPremium(premium);
        setMode(premium ? 'spotify-sdk' : 'spotify-preview');

        if (premium) {
          initSDKPlayer(token);
        }
      });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function initSDKPlayer(token) {
    const sdk = new SpotifySDKPlayer();
    sdk._onTrackEnd = () => advanceSDKTrack();
    try {
      await sdk.init(() => {
        // Keep the token fresh for every SDK request
        return getSpotifyToken().then(t => {
          spotifyTokenRef.current = t;
          return t;
        });
      });
      sdkPlayerRef.current = sdk;
      analyserConnectedRef.current = false; // SDK audio not wired to Web Audio
    } catch (err) {
      console.error('Spotify SDK init failed:', err);
      // Fall back to preview mode if Premium SDK fails (e.g. account error)
      setMode('spotify-preview');
      setIsPremium(false);
    }
  }

  function advanceSDKTrack() {
    const code = sdkCurrentCountryRef.current;
    if (!code) return;
    const tracks = trackCacheRef.current[code];
    if (!tracks || tracks.length === 0) return;
    const idx = ((trackIndexRef.current[code] || 0) + 1) % tracks.length;
    trackIndexRef.current[code] = idx;
    if (playingRef.current && sdkPlayerRef.current && tracks[idx]?.uri) {
      sdkPlayerRef.current.playTrack(tracks[idx].uri);
    }
  }

  // ── Track-end handlers for dual-channel HTML audio ─────────────────────────
  useEffect(() => {
    const makeHandler = channelId => () => {
      const code = channelAssignment.current[channelId];
      if (!code) return;
      const tracks = trackCacheRef.current[code];
      if (!tracks || tracks.length === 0) return;
      const idx = ((trackIndexRef.current[code] || 0) + 1) % tracks.length;
      trackIndexRef.current[code] = idx;
      const track = tracks[idx];
      if (playingRef.current && track?.preview_url) {
        playOnChannel(channelId, track.preview_url);
      }
    };

    const elA = getAudioElement('A');
    const elB = getAudioElement('B');
    const handlerA = makeHandler('A');
    const handlerB = makeHandler('B');
    elA.addEventListener('ended', handlerA);
    elB.addEventListener('ended', handlerB);
    return () => {
      elA.removeEventListener('ended', handlerA);
      elB.removeEventListener('ended', handlerB);
    };
  }, []);

  // ── Mixer (dual-channel modes only) ──────────────────────────────────────
  const ensureMixer = useCallback(() => {
    if (mixerRef.current) return;
    mixerRef.current = new AudioMixer();
    mixerRef.current.addChannel('A', getAudioElement('A'));
    mixerRef.current.addChannel('B', getAudioElement('B'));
    analyserConnectedRef.current = true;
  }, []);

  // ── Track fetching ─────────────────────────────────────────────────────────
  const fetchTracksForCountry = useCallback(async (countryCode) => {
    if (trackCacheRef.current[countryCode] || fetchingRef.current[countryCode]) return;
    fetchingRef.current[countryCode] = true;

    try {
      let tracks;
      const currentMode = mode; // capture at call time

      if ((currentMode === 'spotify-preview' || currentMode === 'spotify-sdk') && spotifyTokenRef.current) {
        tracks = await searchSpotify(countryCode, spotifyTokenRef.current);
        // For preview mode, drop tracks without a 30s clip
        if (currentMode === 'spotify-preview') {
          tracks = tracks.filter(t => t.preview_url);
        }
      } else {
        tracks = await searchItunes(countryCode);
      }

      // Fallback to iTunes if Spotify returned nothing playable
      if ((!tracks || tracks.length === 0) && currentMode !== 'itunes') {
        tracks = await searchItunes(countryCode);
      }

      trackCacheRef.current[countryCode] = tracks || [];
    } catch (err) {
      console.error('Failed to fetch tracks for', countryCode, err);
      trackCacheRef.current[countryCode] = [];
    } finally {
      fetchingRef.current[countryCode] = false;
    }
  }, [mode]);

  // ── Dual-channel: start a country on a channel ────────────────────────────
  const startCountryOnChannel = useCallback((channelId, countryCode) => {
    const tracks = trackCacheRef.current[countryCode];
    if (!tracks || tracks.length === 0) {
      fetchTracksForCountry(countryCode).then(() => {
        const fetched = trackCacheRef.current[countryCode];
        if (
          fetched && fetched.length > 0 &&
          channelAssignment.current[channelId] === countryCode &&
          playingRef.current
        ) {
          const idx = trackIndexRef.current[countryCode] || 0;
          if (fetched[idx]?.preview_url) playOnChannel(channelId, fetched[idx].preview_url);
        }
      });
      return;
    }
    if (playingRef.current) {
      const idx = trackIndexRef.current[countryCode] || 0;
      if (tracks[idx]?.preview_url) playOnChannel(channelId, tracks[idx].preview_url);
    }
  }, [fetchTracksForCountry]);

  // ── SDK: start the current country ────────────────────────────────────────
  const startSDKCountry = useCallback(async (countryCode) => {
    const sdk = sdkPlayerRef.current;
    if (!sdk || !playingRef.current) return;

    const tracks = trackCacheRef.current[countryCode];
    if (!tracks || tracks.length === 0) {
      await fetchTracksForCountry(countryCode);
      const fetched = trackCacheRef.current[countryCode];
      if (!fetched || fetched.length === 0) return;
      if (sdkCurrentCountryRef.current !== countryCode) return; // superseded
      const idx = trackIndexRef.current[countryCode] || 0;
      if (fetched[idx]?.uri) sdk.playTrack(fetched[idx].uri);
      return;
    }

    const idx = trackIndexRef.current[countryCode] || 0;
    if (tracks[idx]?.uri) sdk.playTrack(tracks[idx].uri);
  }, [fetchTracksForCountry]);

  // ── Main scroll → audio update ─────────────────────────────────────────────
  const updateScrollAudio = useCallback((scrollState, locations) => {
    const { prevIndex, nextIndex, blend, volumePrev, volumeNext } = scrollState;

    const prevCountry = locations[prevIndex]?.country;
    const nextCountry = locations[nextIndex]?.country;
    const prevCode = prevCountry ? getCountryCode(prevCountry) : null;
    const nextCode = nextCountry ? getCountryCode(nextCountry) : null;

    // ── SDK (Premium) mode ────────────────────────────────────────────────
    if (mode === 'spotify-sdk') {
      const dominantCode = blend < 0.5 ? prevCode : nextCode;

      // Switch track when dominant country changes
      if (dominantCode && dominantCode !== sdkCurrentCountryRef.current) {
        sdkCurrentCountryRef.current = dominantCode;
        startSDKCountry(dominantCode);
      }

      // Pause at Start (no country)
      if (!dominantCode && sdkPlayerRef.current && playingRef.current) {
        sdkPlayerRef.current.pause();
      }

      // Volume: dips gently at the midpoint (blend = 0.5) where the track switches
      // 1.0 when firmly in a country, 0.3 at the exact crossover
      const sdkVol = 0.3 + 0.7 * Math.abs(blend * 2 - 1);
      if (sdkPlayerRef.current) sdkPlayerRef.current.setVolume(sdkVol);

      // Expose single-channel assignment for Globe frequency map
      channelAssignmentRef.current = { A: dominantCode, B: null };

      // Prefetch adjacent countries
      [prevIndex - 1, nextIndex + 1].forEach(i => {
        if (i >= 0 && i < locations.length && locations[i].country) {
          const code = getCountryCode(locations[i].country);
          if (code) fetchTracksForCountry(code);
        }
      });

      return;
    }

    // ── Dual-channel mode (iTunes / spotify-preview) ──────────────────────
    const assign = channelAssignment.current;
    const neededCodes = new Set([prevCode, nextCode].filter(Boolean));

    // Free channels no longer needed
    ['A', 'B'].forEach(ch => {
      if (assign[ch] && !neededCodes.has(assign[ch])) {
        pauseChannel(ch);
        assign[ch] = null;
      }
    });

    // Assign needed countries to free channels
    neededCodes.forEach(code => {
      if (assign.A === code || assign.B === code) return;
      const freeCh = assign.A === null ? 'A' : assign.B === null ? 'B' : null;
      if (!freeCh) return;
      assign[freeCh] = code;
      startCountryOnChannel(freeCh, code);
    });

    // Volume crossfade
    if (mixerRef.current) {
      ['A', 'B'].forEach(ch => {
        let vol = 0;
        if (assign[ch] === prevCode && prevCode) vol = volumePrev;
        if (assign[ch] === nextCode && nextCode) vol = volumeNext;
        if (prevCode && nextCode && prevCode === nextCode && assign[ch] === prevCode) vol = 1;
        mixerRef.current.setChannelVolume(ch, vol);
      });
    }

    channelAssignmentRef.current = { A: assign.A, B: assign.B };

    // Prefetch adjacent countries
    [prevIndex - 1, nextIndex + 1].forEach(i => {
      if (i >= 0 && i < locations.length && locations[i].country) {
        const code = getCountryCode(locations[i].country);
        if (code) fetchTracksForCountry(code);
      }
    });
  }, [mode, startCountryOnChannel, startSDKCountry, fetchTracksForCountry]);

  // ── Play / Pause ──────────────────────────────────────────────────────────
  const togglePlayPause = useCallback(() => {
    if (playing) {
      // Pause
      if (mode === 'spotify-sdk') {
        sdkPlayerRef.current?.pause();
      } else {
        pauseAll();
      }
      setPlaying(false);
      playingRef.current = false;
    } else {
      // Play
      playingRef.current = true;

      if (mode === 'spotify-sdk') {
        const code = sdkCurrentCountryRef.current;
        if (code) {
          startSDKCountry(code);
        }
      } else {
        ensureMixer();
        const assign = channelAssignment.current;
        ['A', 'B'].forEach(ch => {
          if (!assign[ch]) return;
          const tracks = trackCacheRef.current[assign[ch]];
          const idx = trackIndexRef.current[assign[ch]] || 0;
          if (tracks?.[idx]?.preview_url) playOnChannel(ch, tracks[idx].preview_url);
        });
      }

      setPlaying(true);
    }
  }, [playing, mode, ensureMixer, startSDKCountry]);

  // ── Frequency data (dual-channel modes) ───────────────────────────────────
  const updateFrequencyData = useCallback(() => {
    if (!mixerRef.current || !freqTextureRef.current) return;
    const data = mixerRef.current.getFrequencyData();
    freqTextureRef.current.update(data);
    const dataA = mixerRef.current.getChannelFrequencyData('A');
    const dataB = mixerRef.current.getChannelFrequencyData('B');
    if (dataA && channelFreqTextureARef.current) channelFreqTextureARef.current.update(dataA);
    if (dataB && channelFreqTextureBRef.current) channelFreqTextureBRef.current.update(dataB);
  }, []);

  // ── Spotify auth actions (exposed to UI) ───────────────────────────────────
  const connectSpotify = useCallback(() => {
    initiateSpotifyAuth(); // redirects to Spotify
  }, []);

  const disconnectSpotify = useCallback(() => {
    clearSpotifyAuth();
    sdkPlayerRef.current?.disconnect();
    sdkPlayerRef.current = null;
    sdkCurrentCountryRef.current = null;
    trackCacheRef.current = {};
    trackIndexRef.current = {};
    setSpotifyConnected(false);
    setIsPremium(false);
    setMode('itunes');
    setPlaying(false);
    playingRef.current = false;
    pauseAll();
  }, []);

  return {
    isPlaying: playing,
    mode,
    spotifyAuth: {
      isConnected: spotifyConnected,
      isPremium,
      login: connectSpotify,
      logout: disconnectSpotify,
    },
    togglePlayPause,
    updateScrollAudio,
    updateFrequencyData,
    frequencyTextureRef,
    channelFreqTexturesRef,
    channelAssignmentRef,
    audioReactiveRef,
    analyserConnected: analyserConnectedRef,
  };
}
